import{_ as s,a,c as n,b as o}from"./chunks/framework.b9WMfGr4.js";const h=JSON.parse('{"title":"04-资源引用与就近原则","description":"规范技术博客的本地专属插图就近存放原则、在线图床防盗链策略与全站静态资源边界。","frontmatter":{"title":"04-资源引用与就近原则","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"规范技术博客的本地专属插图就近存放原则、在线图床防盗链策略与全站静态资源边界。","tags":["写作规范","静态资源"]},"headers":[],"relativePath":"posts/0-博客指南/博客的写作规范/04-资源引用与就近原则.md","filePath":"posts/0-博客指南/博客的写作规范/04-资源引用与就近原则.md"}'),r={name:"posts/0-博客指南/博客的写作规范/04-资源引用与就近原则.md"};function t(l,e,i,p,c,d){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_04-资源引用与就近原则" tabindex="-1">04-资源引用与就近原则 <a class="header-anchor" href="#_04-资源引用与就近原则" aria-label="Permalink to &quot;04-资源引用与就近原则&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>图片与静态资源是技术文档中重要的视觉论据。为了保证文档具备自包含性并防止全站资源目录混乱，博客制定了严格的资源存放与引用规范。</p><h2 id="_1-本地插图就近原则" tabindex="-1">1. 本地插图就近原则 <a class="header-anchor" href="#_1-本地插图就近原则" aria-label="Permalink to &quot;1. 本地插图就近原则&quot;">​</a></h2><p>在以往的静态博客维护中，常常存在将所有图片集中丢在全站根目录静态文件夹的现象，导致文档移动或重命名时图片链接大规模失效，且无法辨识某张废弃图片归属于哪一篇文章。</p><p>为此，博客全面贯彻同级收拢的就近原则：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>posts/分类目录/</span></span>
<span class="line"><span>  ├── 01-实战分析.md</span></span>
<span class="line"><span>  ├── 02-架构拆解.md</span></span>
<span class="line"><span>  └── assets/                      # 本地专属插图专用目录</span></span>
<span class="line"><span>        ├── system-architecture.png</span></span>
<span class="line"><span>        └── call-trace.svg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>同级目录就近管理</strong>：某篇文章独占引用的本地截图、架构手稿与矢量插图，必须统一存放在该文档同级目录下的 <code>assets/</code> 子目录中。</li><li><strong>相对路径引用</strong>：在 Markdown 中直接使用 <code>./assets/文件名.png</code> 相对路径方式引用。</li><li><strong>自包含与高便携度</strong>：整个目录可被随时整体迁移、打包或备份，内部图片链接始终保持相对有效，杜绝全站散落碎片文件。</li></ul><h2 id="_2-在线图床与免-referer-防盗链机制" tabindex="-1">2. 在线图床与免 Referer 防盗链机制 <a class="header-anchor" href="#_2-在线图床与免-referer-防盗链机制" aria-label="Permalink to &quot;2. 在线图床与免 Referer 防盗链机制&quot;">​</a></h2><p>针对大型高清照片、公共图床或第三方对象存储托管的高频图片，支持直接引用标准在线 URL 链接：</p><ul><li><strong>标准网络协议</strong>：使用完整的 <code>https://</code> 链接直接插入。</li><li><strong>防盗链全局解决</strong>：很多公共图床与代码托管平台会对 HTTP 请求中的 Referer 来源进行严格校验，导致图片在个人独立博客域名下被拦截报 403 错误。博客在站点元数据与图片渲染插件中全局注入了 <code>referrerpolicy=&quot;no-referrer&quot;</code> 策略，彻底解除防盗链拦截，确保图片顺畅加载。</li></ul><h2 id="_3-全站全局静态资源边界" tabindex="-1">3. 全站全局静态资源边界 <a class="header-anchor" href="#_3-全站全局静态资源边界" aria-label="Permalink to &quot;3. 全站全局静态资源边界&quot;">​</a></h2><p>项目根目录下的 <code>public/</code> 目录属于全站全局唯一资产目录，具备严格的归档边界：</p><ul><li><strong>准入资产范围</strong>：仅允许存放全站共用的单例基础设施文件，例如 GitHub Pages 自定义域名映射配置文件 <code>CNAME</code>、浏览器标头图标 <code>favicon.ico</code> 等。</li><li><strong>严禁滥用</strong>：严禁将某篇单独博文的插图或临时演示文件丢入 <code>public/</code> 目录中，防止公共根目录不断膨胀恶化。</li></ul>`,14)])])}const _=s(r,[["render",t]]);export{h as __pageData,_ as default};
